type templatePart struct {
	Literal string
	Setting *templateSetting
}

type templateSetting struct {
	Key        string
	Operator   string
	Prefix     string
	DefaultRaw string
}

type configTemplate struct {
	Parts      []templatePart
	Order      []string
	Defaults   map[string]string
	Prefixes   map[string]string
	Operators  map[string]string
}

type parsedConfig struct {
	Raw map[string]string
}

func parseConfigTemplate(text string) (*configTemplate, error) {
	lines := splitLines(text)
	parts := make([]templatePart, 0, len(lines))
	order := make([]string, 0, 512)
	defaults := make(map[string]string, 512)
	prefixes := make(map[string]string, 512)
	operators := make(map[string]string, 512)

