	for i := 0; i < len(lines); {
		line := lines[i]
		lineNoNL := trimTrailingLF(line)
		matchIdx := assignmentPattern.FindStringSubmatchIndex(lineNoNL)
		if matchIdx == nil {
			literal.WriteString(line)
			i++
			continue
		}
