			Key:        key,
			Operator:   op,
			Prefix:     prefix,
			DefaultRaw: raw,
		}
		parts = append(parts, templatePart{Setting: setting})
		order = append(order, key)
		defaults[key] = raw
		prefixes[key] = prefix
		operators[key] = op
		i++
	}
	if literal.Len() > 0 {
		parts = append(parts, templatePart{Literal: literal.String()})
	}
	return &configTemplate{
		Parts:     parts,
		Order:     order,
