+	AbsPath        string
+	DisplayName    string
+	BasePageName   string
+	HTMLPage       string
+	HTMLSourcePage string
+	LaTeXPage      string
+	Description    string
+	Functions      []docMember
+	Variables      []docMember
+	SourceLines    []string
+	HasSourcePage  bool
+}
+
+func runDocumentation(res *resources, cfg *parsedConfig, quiet bool, cwd string) error {
+	settings := docSettingsFromConfig(res, cfg, cwd, quiet)
+	files, searchedDirs := collectInputFiles(settings.Inputs, settings.FilePatterns, settings.Recursive, cwd)
+
+	docFiles := make([]docFile, 0, len(files))
+	for _, absPath := range files {
+		parsed, err := parseDocFile(absPath, settings.VerbatimHeader)
+		if err != nil {
+			continue
+		}
+		docFiles = append(docFiles, parsed)
+	}
+
+	emitDocumentationWarnings(docFiles, settings.WarnUndoc)
+	if len(docFiles) == 0 {
+		fmt.Fprintln(os.Stderr, "warning: No files to be processed, please check your settings, in particular INPUT, FILE_PATTERNS, and RECURSIVE")
+	}
+	if !settings.Quiet {
+		emitProgress(docFiles, searchedDirs)
+	}
+
+	if settings.GenerateHTML {
+		if err := generateHTMLDocumentation(res, settings, docFiles); err != nil {
+			return err
+		}
+	}
+	if settings.GenerateLaTeX {
+		if err := generateLaTeXDocumentation(res, settings, docFiles); err != nil {
+			return err
+		}
+	}
+	return nil
+}
+
+func docSettingsFromConfig(res *resources, cfg *parsedConfig, cwd string, quietFlag bool) docSettings {
+	tmpl := res.fullTemplate
+	project := projectMeta{
+		Name:   configString(effectiveRaw(cfg, tmpl, "PROJECT_NAME")),
+		Number: configString(effectiveRaw(cfg, tmpl, "PROJECT_NUMBER")),
+		Brief:  configString(effectiveRaw(cfg, tmpl, "PROJECT_BRIEF")),
+	}
+	if project.Name == "" {
+		project.Name = "My Project"
+	}
+
+	outputDir := configString(effectiveRaw(cfg, tmpl, "OUTPUT_DIRECTORY"))
+	if outputDir == "" {
+		outputDir = cwd
+	} else if !filepath.IsAbs(outputDir) {
+		outputDir = filepath.Join(cwd, outputDir)
+	}
+
+	htmlOutput := configString(effectiveRaw(cfg, tmpl, "HTML_OUTPUT"))
+	if htmlOutput == "" {
+		htmlOutput = "html"
+	}
+	latexOutput := configString(effectiveRaw(cfg, tmpl, "LATEX_OUTPUT"))
+	if latexOutput == "" {
+		latexOutput = "latex"
+	}
+
+	inputs := tokenizeConfigValue(effectiveRaw(cfg, tmpl, "INPUT"))
+	if len(inputs) == 0 {
+		inputs = []string{"."}
+	}
+
+	return docSettings{
+		Project:        project,
+		OutputDir:      outputDir,
+		HTMLOutputDir:  filepath.Join(outputDir, htmlOutput),
+		LaTeXOutputDir: filepath.Join(outputDir, latexOutput),
+		GenerateHTML:   configBool(effectiveRaw(cfg, tmpl, "GENERATE_HTML")),
+		GenerateLaTeX:  configBool(effectiveRaw(cfg, tmpl, "GENERATE_LATEX")),
+		Recursive:      configBool(effectiveRaw(cfg, tmpl, "RECURSIVE")),
+		VerbatimHeader: configBool(effectiveRaw(cfg, tmpl, "VERBATIM_HEADERS")),
+		WarnUndoc:      configBool(effectiveRaw(cfg, tmpl, "WARN_IF_UNDOCUMENTED")),
+		FilePatterns:   tokenizeConfigValue(effectiveRaw(cfg, tmpl, "FILE_PATTERNS")),
+		Inputs:         inputs,
+		Quiet:          quietFlag || configBool(effectiveRaw(cfg, tmpl, "QUIET")),
+	}
+}
+
+func collectInputFiles(inputs, patterns []string, recursive bool, cwd string) ([]string, []string) {
+	seen := make(map[string]bool)
+	var files []string
+	var dirs []string
+	for _, input := range inputs {
+		if input == "" {
+			continue
+		}
+		resolved := input
+		if !filepath.IsAbs(resolved) {
+			resolved = filepath.Join(cwd, resolved)
+		}
+		info, err := os.Stat(resolved)
+		if err != nil {
+			continue
+		}
+		if info.IsDir() {
+			dirs = append(dirs, resolved)
+			if recursive {
+				filepath.WalkDir(resolved, func(path string, d os.DirEntry, walkErr error) error {
+					if walkErr != nil || d.IsDir() {
+						return nil
+					}
+					if matchesFilePattern(filepath.Base(path), patterns) && !seen[path] {
+						seen[path] = true
+						files = append(files, path)
+					}
+					return nil
+				})
+			} else {
+				entries, readErr := os.ReadDir(resolved)
+				if readErr != nil {
+					continue
+				}
+				for _, entry := range entries {
+					if entry.IsDir() {
+						continue
+					}
+					path := filepath.Join(resolved, entry.Name())
+					if matchesFilePattern(entry.Name(), patterns) && !seen[path] {
+						seen[path] = true
+						files = append(files, path)
+					}
+				}
+			}
+			continue
+		}
+		if !seen[resolved] {
+			seen[resolved] = true
+			files = append(files, resolved)
+		}
+	}
+	sort.Strings(files)
+	sort.Strings(dirs)
+	return files, dirs
+}
+
+func matchesFilePattern(name string, patterns []string) bool {
+	if len(patterns) == 0 {
+		return false
+	}
+	for _, pattern := range patterns {
+		ok, err := filepath.Match(pattern, name)
+		if err == nil && ok {
+			return true
+		}
+	}
+	return false
+}
+
+func parseDocFile(absPath string, verbatimHeaders bool) (docFile, error) {
+	data, err := os.ReadFile(absPath)
+	if err != nil {
+		return docFile{}, err
+	}
+	text := strings.ReplaceAll(string(data), "\r\n", "\n")
+	lines := strings.Split(text, "\n")
+	if len(lines) > 0 && lines[len(lines)-1] == "" {
+		lines = lines[:len(lines)-1]
+	}
+
+	display := filepath.Base(absPath)
+	base := encodeDoxygenFileBase(display)
+	fileDoc := docFile{
+		AbsPath:      absPath,
+		DisplayName:  display,
+		BasePageName: base,
+		HTMLPage:     base + ".html",
+		LaTeXPage:    base + ".tex",
+		SourceLines:  append([]string(nil), lines...),
+	}
+	if verbatimHeaders && isHeaderLike(display) {
+		fileDoc.HasSourcePage = true
+		fileDoc.HTMLSourcePage = base + "_source.html"
+	}
+
+	braceDepth := 0
+	pendingDoc := ""
+	for i := 0; i < len(lines); {
+		trimmed := strings.TrimSpace(lines[i])
+		if strings.HasPrefix(trimmed, "/**") || strings.HasPrefix(trimmed, "/*!") {
+			blockLines, end := collectBlockDoc(lines, fileDoc.SourceLines, i)
+			isFile, docText := normalizeDocBlock(blockLines)
+			if isFile {
+				fileDoc.Description = docText
+			} else if docText != "" {
+				pendingDoc = docText
+			}
+			i = end + 1
+			continue
+		}
+		if strings.HasPrefix(trimmed, "///") || strings.HasPrefix(trimmed, "//!") {
+			blockLines, end := collectLineDoc(lines, fileDoc.SourceLines, i)
+			isFile, docText := normalizeDocBlock(blockLines)
+			if isFile {
+				fileDoc.Description = docText
+			} else if docText != "" {
+				pendingDoc = docText
+			}
+			i = end + 1
+			continue
+		}
+
+		line := stripNonDocComment(lines[i])
+		if braceDepth == 0 {
+			if member, ok := parseFunctionMember(line, display, pendingDoc != ""); ok {
+				member.Line = i + 1
+				member.Anchor = hashAnchor(display, member)
+				fileDoc.Functions = append(fileDoc.Functions, member)
+				pendingDoc = ""
+			} else if member, ok := parseVariableMember(line, display, pendingDoc != ""); ok {
+				member.Line = i + 1
+				member.Anchor = hashAnchor(display, member)
+				fileDoc.Variables = append(fileDoc.Variables, member)
+				pendingDoc = ""
+			} else if trimmed != "" && !strings.HasPrefix(trimmed, "#") {
+				pendingDoc = ""
+			}
+		}
+		braceDepth += netBraceDelta(line)
+		if braceDepth < 0 {
+			braceDepth = 0
+		}
+		i++
+	}
+
+	return fileDoc, nil
+}
+
+func collectBlockDoc(lines []string, sourceLines []string, start int) ([]string, int) {
+	var docLines []string
+	for i := start; i < len(lines); i++ {
+		sourceLines[i] = ""
+		line := lines[i]
+		if i == start {
+			line = strings.TrimPrefix(strings.TrimPrefix(line, "/**"), "/*!")
+		}
+		if end := strings.Index(line, "*/"); end >= 0 {
+			docLines = append(docLines, cleanDocLine(line[:end]))
+			return docLines, i
+		}
+		docLines = append(docLines, cleanDocLine(line))
+	}
+	return docLines, len(lines) - 1
+}
+
+func collectLineDoc(lines []string, sourceLines []string, start int) ([]string, int) {
+	var docLines []string
+	i := start
+	for ; i < len(lines); i++ {
+		trimmed := strings.TrimSpace(lines[i])
+		if !(strings.HasPrefix(trimmed, "///") || strings.HasPrefix(trimmed, "//!")) {
+			break
+		}
+		sourceLines[i] = ""
+		docLines = append(docLines, strings.TrimSpace(strings.TrimPrefix(strings.TrimPrefix(trimmed, "///"), "//!")))
+	}
+	return docLines, i - 1
+}
+
+func cleanDocLine(line string) string {
+	trimmed := strings.TrimSpace(line)
+	trimmed = strings.TrimPrefix(trimmed, "*")
+	return strings.TrimSpace(trimmed)
+}
+
+func normalizeDocBlock(lines []string) (bool, string) {
+	first := -1
+	for i, line := range lines {
+		if strings.TrimSpace(line) != "" {
+			first = i
+			break
+		}
+	}
+	if first == -1 {
+		return false, ""
+	}
+	line := strings.TrimSpace(lines[first])
+	isFile := false
+	if strings.HasPrefix(line, "@file") || strings.HasPrefix(line, `\file`) {
+		isFile = true
+		line = strings.TrimSpace(strings.TrimPrefix(strings.TrimPrefix(line, "@file"), `\file`))
+		lines[first] = line
+	} else if strings.HasPrefix(line, "@brief") || strings.HasPrefix(line, `\brief`) {
+		line = strings.TrimSpace(strings.TrimPrefix(strings.TrimPrefix(line, "@brief"), `\brief`))
+		lines[first] = line
+	}
+
+	var parts []string
+	for _, part := range lines {
+		part = strings.TrimSpace(part)
+		if part == "" {
+			continue
+		}
+		parts = append(parts, part)
+	}
+	return isFile, strings.Join(parts, " ")
+}
+
+func stripNonDocComment(line string) string {
+	if idx := strings.Index(line, "//"); idx >= 0 {
+		if idx == 0 || (idx > 0 && line[idx-1] != ':' && line[idx-1] != '\\') {
+			return line[:idx]
+		}
+	}
+	return line
+}
+
+func parseFunctionMember(line, display string, documented bool) (docMember, bool) {
+	match := functionPattern.FindStringSubmatch(line)
+	if match == nil {
+		return docMember{}, false
+	}
+	name := match[2]
+	if isControlWord(name) {
+		return docMember{}, false
+	}
+	return docMember{
+		Kind:       "function",
+		Type:       collapseSpaces(match[1]),
+		Name:       name,
+		Args:       strings.TrimSpace(match[3]),
+		Documented: documented,
+	}, true
+}
+
+func parseVariableMember(line, display string, documented bool) (docMember, bool) {
+	match := variablePattern.FindStringSubmatch(line)
+	if match == nil {
+		return docMember{}, false
+	}
+	typeText := collapseSpaces(match[1])
+	if strings.HasPrefix(typeText, "return") || strings.HasPrefix(typeText, "typedef") {
+		return docMember{}, false
+	}
+	return docMember{
+		Kind:       "variable",
+		Type:       typeText,
+		Name:       match[2],
+		Documented: documented,
+	}, true
+}
+
+func isControlWord(name string) bool {
+	switch name {
+	case "if", "for", "while", "switch", "return":
+		return true
+	default:
+		return false
+	}
+}
+
+func collapseSpaces(value string) string {
+	return strings.Join(strings.Fields(value), " ")
+}
+
+func netBraceDelta(line string) int {
+	return strings.Count(line, "{") - strings.Count(line, "}")
+}
+
+func hashAnchor(display string, member docMember) string {
+	sum := md5.Sum([]byte(display + ":" + member.Kind + ":" + member.Type + ":" + member.Name + ":" + member.Args))
+	return hex.EncodeToString(sum[:])
+}
+
+func isHeaderLike(name string) bool {
+	ext := strings.ToLower(filepath.Ext(name))
+	switch ext {
+	case ".h", ".hh", ".hpp", ".hxx", ".inc":
+		return true
+	default:
+		return false
+	}
+}
+
+func emitDocumentationWarnings(files []docFile, warnUndoc bool) {
+	if !warnUndoc {
+		return
+	}
+	for _, file := range files {
+		for _, member := range file.Functions {
+			if member.Documented {
+				continue
+			}
+			fmt.Fprintf(os.Stderr, "%s:%d: warning: Member %s(%s) (function) of file %s is not documented.\n",
+				file.AbsPath, member.Line, member.Name, member.Args, file.DisplayName)
+		}
+		for _, member := range file.Variables {
+			if member.Documented {
+				continue
+			}
+			fmt.Fprintf(os.Stderr, "%s:%d: warning: Member %s (variable) of file %s is not documented.\n",
+				file.AbsPath, member.Line, member.Name, file.DisplayName)
+		}
+	}
+}
