+func generateHTMLDocumentation(res *resources, settings docSettings, files []docFile) error {
+	if err := os.MkdirAll(settings.HTMLOutputDir, 0o755); err != nil {
+		return err
+	}
+	if err := copyAssetDir(settings.HTMLOutputDir, "assets/html_static"); err != nil {
+		return err
+	}
+
+	if err := writeTextFile(filepath.Join(settings.HTMLOutputDir, "index.html"), renderIndexHTML(settings.Project)); err != nil {
+		return err
+	}
+	if err := writeTextFile(filepath.Join(settings.HTMLOutputDir, "menudata.js"), renderMenuDataJS(files)); err != nil {
+		return err
+	}
+	if err := writeTextFile(filepath.Join(settings.HTMLOutputDir, "navtreedata.js"), renderNavTreeDataJS(settings.Project, files)); err != nil {
+		return err
+	}
+	if err := writeTextFile(filepath.Join(settings.HTMLOutputDir, "navtreeindex0.js"), renderNavTreeIndexJS(files)); err != nil {
+		return err
+	}
+	if err := writeTextFile(filepath.Join(settings.HTMLOutputDir, "search", "searchdata.js"), renderSearchDataJS(files)); err != nil {
+		return err
+	}
+
+	if len(files) == 0 {
+		return nil
+	}
+
+	if err := writeTextFile(filepath.Join(settings.HTMLOutputDir, "files.html"), renderFilesHTML(settings.Project, files)); err != nil {
+		return err
+	}
+	if err := writeTextFile(filepath.Join(settings.HTMLOutputDir, "files_dup.js"), renderFilesDupJS(files)); err != nil {
+		return err
+	}
+	if err := writeTextFile(filepath.Join(settings.HTMLOutputDir, "search", "all_0.js"), renderSearchEntriesJS(files)); err != nil {
+		return err
+	}
+	if err := writeTextFile(filepath.Join(settings.HTMLOutputDir, "search", "files_0.js"), renderSearchEntriesJS(files)); err != nil {
+		return err
+	}
+
+	for _, file := range files {
+		if err := writeTextFile(filepath.Join(settings.HTMLOutputDir, file.HTMLPage), renderFileReferenceHTML(settings.Project, file)); err != nil {
+			return err
+		}
+		if file.HasSourcePage {
+			if err := writeTextFile(filepath.Join(settings.HTMLOutputDir, file.HTMLSourcePage), renderSourceHTML(settings.Project, file)); err != nil {
+				return err
+			}
+		}
+	}
+	return nil
+}
+
+func generateLaTeXDocumentation(res *resources, settings docSettings, files []docFile) error {
+	if err := os.MkdirAll(settings.LaTeXOutputDir, 0o755); err != nil {
+		return err
+	}
+	for _, asset := range []string{"Makefile", "doxygen.sty", "etoc_doxygen.sty"} {
+		if err := copyAssetFile(filepath.Join(settings.LaTeXOutputDir, asset), filepath.ToSlash(filepath.Join("assets/latex_static", asset))); err != nil {
+			return err
+		}
+	}
+	if err := writeTextFile(filepath.Join(settings.LaTeXOutputDir, "refman.tex"), renderRefmanTeX(res.latexRefmanEmpty, settings.Project, files)); err != nil {
+		return err
+	}
+	if len(files) == 0 {
+		return nil
+	}
+	if err := writeTextFile(filepath.Join(settings.LaTeXOutputDir, "files.tex"), renderFilesTeX(files)); err != nil {
+		return err
+	}
+	for _, file := range files {
+		if err := writeTextFile(filepath.Join(settings.LaTeXOutputDir, file.LaTeXPage), renderFileTeX(file)); err != nil {
+			return err
+		}
+	}
+	return nil
+}
