+func renderIndexHTML(project projectMeta) string {
+	body := `<a href="doxygen_crawl.html"></a>`
+	return renderHTMLPage(project, "Main Page", project.Name+" Documentation", "index.html", body, "", false)
+}
+
+func renderFilesHTML(project projectMeta, files []docFile) string {
+	var body strings.Builder
+	body.WriteString(`<div class="textblock">Here is a list of all documented files with brief descriptions:</div><div class="directory">` + "\n")
+	body.WriteString(`<table class="directory">` + "\n")
+	for i, file := range files {
+		rowClass := "even"
+		if i%2 == 1 {
+			rowClass = "odd"
+		}
+		fmt.Fprintf(&body, `<tr id="row_%d_" class="%s"><td class="entry"><span style="width:16px;display:inline-block;">&#160;</span><span class="icondoc"><div class="doc-icon"></div></span><a class="el" href="%s" target="_self">%s</a></td><td class="desc"></td></tr>`+"\n",
+			i, rowClass, file.HTMLPage, html.EscapeString(file.DisplayName))
+	}
+	body.WriteString(`</table>` + "\n")
+	body.WriteString(`</div><!-- directory -->`)
+	return renderHTMLPage(project, "File List", "File List", "files.html", body.String(), "", false)
+}
+
+func renderFileReferenceHTML(project projectMeta, file docFile) string {
+	var body strings.Builder
+	if file.HasSourcePage {
+		fmt.Fprintf(&body, "\n<p><a href=\"%s\">Go to the source code of this file.</a></p>\n", file.HTMLSourcePage)
+	}
+	if len(file.Functions) > 0 {
+		body.WriteString(renderMemberTableHTML("Functions", "func-members", file.Functions))
+	}
+	if len(file.Variables) > 0 {
+		body.WriteString(renderMemberTableHTML("Variables", "var-members", file.Variables))
+	}
+	if file.Description != "" {
+		body.WriteString("\n<a name=\"details\" id=\"details\"></a><h2 id=\"header-details\" class=\"groupheader\">Detailed Description</h2>\n")
+		body.WriteString(`<div class="textblock"><p>` + html.EscapeString(file.Description) + ` </p>` + "\n</div>")
+	}
+	pageTitle := file.DisplayName + " File Reference"
+	footer := fmt.Sprintf(`<li class="navelem"><a href="%s">%s</a></li>`, file.HTMLPage, html.EscapeString(file.DisplayName))
+	return renderHTMLPage(project, pageTitle, pageTitle, file.HTMLPage, body.String(), footer, true)
+}
