+	footer := fmt.Sprintf(`<li class="navelem"><a href="%s">%s</a></li>`, file.HTMLPage, html.EscapeString(file.DisplayName))
+	return renderHTMLPage(project, pageTitle, file.DisplayName, file.HTMLSourcePage, fragment.String(), footer, false)
