+func searchSectionLetters(files []docFile) string {
+	seen := make(map[rune]bool)
+	letters := make([]rune, 0, len(files))
+	for _, file := range files {
+		for _, r := range strings.ToLower(file.DisplayName) {
+			if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') {
+				if !seen[r] {
+					seen[r] = true
+					letters = append(letters, r)
+				}
+				break
+			}
+		}
+	}
+	sort.Slice(letters, func(i, j int) bool { return letters[i] < letters[j] })
+	return string(letters)
+}
