+func encodeDoxygenFileBase(name string) string {
+	var out strings.Builder
+	for _, r := range name {
+		switch {
+		case r == '_':
+			out.WriteString("__")
+		case r == '.':
+			out.WriteString("_8")
+		default:
+			out.WriteRune(r)
+		}
+	}
+	return out.String()
+}
