func renderSourceHTML(project projectMeta, file docFile) string {
	var fragment strings.Builder
	fragment.WriteString(fmt.Sprintf(`<a href="%s">Go to the documentation of this file.</a><div class="fragment">`, file.HTMLPage))
	for i, line := range file.SourceLines {
		lineID := fmt.Sprintf("l%05d", i+1)
		fmt.Fprintf(&fragment, `<div class="line"><a id="%s" name="%s"></a><span class="lineno">%5d</span>`, lineID, lineID, i+1)
		if line != "" {
			fragment.WriteString(highlightSourceLine(line))
		}
		fragment.WriteString(`</div>` + "\n")
	}
	fragment.WriteString(`</div><!-- fragment -->`)
	pageTitle := file.DisplayName + " Source File"
