		fmt.Fprintf(&out, `<tr class="memitem:a%s" id="r_a%s"><td class="memItemLeft"><a id="a%s" name="a%s"></a>`+"\n", member.Anchor, member.Anchor, member.Anchor, member.Anchor)
		fmt.Fprintf(&out, `%s&#160;</td><td class="memItemRight"><b>%s</b>`, html.EscapeString(member.Type), html.EscapeString(member.Name))
