func highlightSourceLine(line string) string {
	escaped := html.EscapeString(line)
	return sourceKeywordPattern.ReplaceAllStringFunc(escaped, func(match string) string {
		return `<span class="keywordtype">` + match + `</span>`
	})
}

func writeTextFile(path string, content string) error {
	dir := filepath.Dir(path)
	if dir != "." {
		if err := os.MkdirAll(dir, 0o755); err != nil {
			return err
		}
	}
	return os.WriteFile(path, []byte(content), 0o644)
}

func encodeDoxygenFileBase(name string) string {
	var out strings.Builder
	for _, r := range name {
		switch {
		case r == '_':
			out.WriteString("__")
		case r == '.':
			out.WriteString("_8")
		default:
			out.WriteRune(r)
		}
	}
	return out.String()
}

func encodeSearchKey(name string) string {
	var out strings.Builder
	for _, b := range []byte(name) {
		switch {
		case (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z') || (b >= '0' && b <= '9'):
			out.WriteByte(byte(strings.ToLower(string([]byte{b}))[0]))
		default:
			fmt.Fprintf(&out, "_%02x", b)
		}
	}
	return out.String()
}

func latexFileDisplay(name string) string {
	escaped := strings.ReplaceAll(name, "_", `\_`)
	return strings.ReplaceAll(escaped, ".", `.\+`)
}

func latexEscapeText(text string) string {
	replacer := strings.NewReplacer(
		`\`, `\textbackslash{}`,
		`{`, `\{`,
		`}`, `\}`,
		`#`, `\#`,
		`$`, `\$`,
		`%`, `\%`,
		`&`, `\&`,
		`_`, `\_`,
		`^`, `\^{}`,
		`~`, `\~{}`,
	)
	return replacer.Replace(text)
}

func escapeJS(text string) string {
	return strings.ReplaceAll(text, `'`, `\'`)
}

