package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

const versionString = "1.17.0 (9135bd68ddc9ea65023d967c75048a7a86a5d495)"

type cliOptions struct {
	short        bool
	quiet        bool
	help         bool
	version      bool
	extended     bool
	generate     bool
	update       bool
	layout       bool
	compare      bool
	compareNoEnv bool
	writeStyle   bool
	writeExt     bool
	listEmoji    bool
	developer    bool
	wFormat      string
	eFormat      string
	fList        string
	positionals  []string
}

type cliError struct {
	Message  string
	ShowHelp bool
}

func (e cliError) Error() string { return e.Message }

func main() {
	res, err := loadResources()
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	opts, err := parseCLI(os.Args[1:])
	if err != nil {
		handleCLIError(err, os.Args[0])
	}

	switch {
	case opts.help:
		fmt.Print(renderHelp(os.Args[0]))
	case opts.version:
		fmt.Println(versionString)
	case opts.extended:
		fmt.Println(versionString)
		fmt.Println("    with sqlite3 3.42.0.")
	case opts.developer && !opts.hasAction() && len(opts.positionals) == 0:
		fmt.Print(renderDeveloperUsage())
	case opts.generate:
		exitOnError(handleGenerate(res, opts))
	case opts.update:
		exitOnError(handleUpdate(res, opts))
	case opts.layout:
		exitOnError(handleWriteSingleOutput(defaultPositional(opts.positionals, "DoxygenLayout.xml"), res.layoutXML))
	case opts.writeStyle:
		exitOnError(handleWriteStyle(res, opts))
	case opts.writeExt:
		exitOnError(handleWriteExtensions(res, opts))
	case opts.compare:
		exitOnError(handleCompare(res, opts, false))
	case opts.compareNoEnv:
		exitOnError(handleCompare(res, opts, true))
	case opts.listEmoji:
		exitOnError(handleListEmoji(res, opts))
	default:
		exitOnError(handleDocRun(res, opts))
	}
}

func exitOnError(err error) {
	if err == nil {
		return
	}
	handleCLIError(err, os.Args[0])
}

func handleCLIError(err error, prog string) {
	var cliErr cliError
	if ok := asCLIError(err, &cliErr); ok {
		fmt.Fprintf(os.Stderr, "error: %s\n", cliErr.Message)
		if cliErr.ShowHelp {
			fmt.Print(renderHelp(prog))
		}
		os.Exit(1)
	}
	fmt.Fprintf(os.Stderr, "error: %v\n", err)
	os.Exit(1)
}

func asCLIError(err error, target *cliError) bool {
	typed, ok := err.(cliError)
	if !ok {
		return false
	}
	*target = typed
	return true
}

func parseCLI(args []string) (cliOptions, error) {
	var opts cliOptions
	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-s":
			opts.short = true
		case "-q":
			opts.quiet = true
		case "-h", "-?":
			opts.help = true
		case "-v":
			opts.version = true
		case "-V":
			opts.extended = true
		case "-g":
			opts.generate = true
		case "-u":
			opts.update = true
		case "-l":
			opts.layout = true
		case "-x":
			opts.compare = true
		case "-x_noenv":
			opts.compareNoEnv = true
		case "-w":
			opts.writeStyle = true
			if i+1 >= len(args) {
				return opts, cliError{Message: `option "-w" is missing format specifier rtf, html or latex`}
			}
			i++
			opts.wFormat = args[i]
		case "-e":
			opts.writeExt = true
			if i+1 >= len(args) {
				return opts, cliError{Message: `option "-e" is missing format specifier rtf.`}
			}
			i++
			opts.eFormat = args[i]
		case "-f":
			opts.listEmoji = true
			if i+1 >= len(args) {
				return opts, cliError{Message: `option "-f" is missing list specifier.`}
			}
			i++
			opts.fList = args[i]
		case "-d":
			if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
				i++
			} else {
				opts.developer = true
			}
		default:
			if strings.HasPrefix(arg, "-") && arg != "-" {
				return opts, cliError{Message: fmt.Sprintf("Unknown option %q", arg), ShowHelp: true}
			}
			opts.positionals = append(opts.positionals, arg)
		}
	}
	return opts, nil
}

func (opts cliOptions) hasAction() bool {
	return opts.generate || opts.update || opts.layout || opts.compare || opts.compareNoEnv || opts.writeStyle || opts.writeExt || opts.listEmoji
}

func handleGenerate(res *resources, opts cliOptions) error {
	target := defaultPositional(opts.positionals, "Doxyfile")
	data := res.fullConfigText
	if opts.short {
		data = res.shortConfigText
	}
	if err := handleWriteSingleOutput(target, data); err != nil {
		return err
	}
	if target == "-" {
		return nil
	}
	suffix := ""
	if target != "Doxyfile" {
		suffix = " " + target
	}
	fmt.Printf("\n\nConfiguration file '%s' created.\n\nNow edit the configuration file and enter\n\n  doxygen%s\n\nto generate the documentation for your project\n\n", target, suffix)
	return nil
}

func handleUpdate(res *resources, opts cliOptions) error {
	target, explicit := defaultConfigPath(opts.positionals)
	text, err := readConfigText(target, explicit)
	if err != nil {
		return err
	}
	parsed := parseConfig(text)
	rendered := renderConfig(res.fullTemplate, parsed)
	if opts.short {
		rendered = renderConfig(res.shortTemplate, parsed)
	}
	if err := handleWriteSingleOutput(target, rendered); err != nil {
		return err
	}
	if target != "-" {
		fmt.Printf("\n\nConfiguration file '%s' updated.\n\n", target)
	}
	return nil
}

func handleCompare(res *resources, opts cliOptions, noEnv bool) error {
	target, explicit := defaultConfigPath(opts.positionals)
	text, err := readConfigText(target, explicit)
	if err != nil {
		return err
	}
	parsed := parseConfig(text)
	fmt.Printf("# Difference with default Doxyfile %s\n", versionString)
	for _, line := range configDiffLines(parsed, res.fullTemplate, noEnv) {
		fmt.Println(line)
	}
	return nil
}

func handleWriteStyle(res *resources, opts cliOptions) error {
	format := strings.ToLower(opts.wFormat)
	switch format {
	case "rtf":
		if len(opts.positionals) < 1 {
			return cliError{Message: `option "-w rtf" is missing a style sheet file name`}
		}
		return handleWriteSingleOutput(opts.positionals[0], res.rtfStyle)
	case "html":
		if len(opts.positionals) < 3 {
			return cliError{Message: `option "-w html" does not have enough arguments`}
		}
		if err := handleWriteSingleOutput(opts.positionals[0], res.htmlHeader); err != nil {
			return err
		}
		if err := handleWriteSingleOutput(opts.positionals[1], res.htmlFooter); err != nil {
			return err
		}
		return handleWriteSingleOutput(opts.positionals[2], res.htmlStyle)
	case "latex":
		if len(opts.positionals) < 3 {
			return cliError{Message: `option "-w latex" does not have enough arguments`}
		}
		if err := handleWriteSingleOutput(opts.positionals[0], res.latexHeader); err != nil {
			return err
		}
		if err := handleWriteSingleOutput(opts.positionals[1], res.latexFooter); err != nil {
			return err
		}
		return handleWriteSingleOutput(opts.positionals[2], res.latexStyle)
	default:
		return cliError{Message: fmt.Sprintf(`Illegal format specifier %q: should be one of rtf, html or latex`, opts.wFormat)}
	}
}

func handleWriteExtensions(res *resources, opts cliOptions) error {
	if strings.ToLower(opts.eFormat) != "rtf" {
		return cliError{Message: `option "-e" has invalid format specifier.`}
	}
	if len(opts.positionals) < 1 {
		return cliError{Message: `option "-e rtf" is missing an extensions file name`}
	}
	return handleWriteSingleOutput(opts.positionals[0], res.rtfExtensions)
}

func handleListEmoji(res *resources, opts cliOptions) error {
	if strings.ToLower(opts.fList) != "emoji" {
		return cliError{Message: `option "-f" has invalid list specifier.`}
	}
	if len(opts.positionals) < 1 {
		return cliError{Message: `option "-f emoji" is missing an output file name`}
	}
	return handleWriteSingleOutput(opts.positionals[0], res.emojiList)
}

func handleDocRun(res *resources, opts cliOptions) error {
	target, explicit := defaultConfigPath(opts.positionals)
	text, err := readConfigText(target, explicit)
	if err != nil {
		return err
	}
	cfg := parseConfig(text)
	cwd, err := os.Getwd()
	if err != nil {
		return err
	}
	return runDocumentation(res, cfg, opts.quiet, cwd)
}

func handleWriteSingleOutput(target, data string) error {
	if target == "-" {
		_, err := io.WriteString(os.Stdout, data)
		return err
	}
	return os.WriteFile(target, []byte(data), 0o644)
}

func readConfigText(path string, explicit bool) (string, error) {
	if path == "-" {
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			return "", err
		}
		return string(data), nil
	}
	data, err := os.ReadFile(path)
	if err == nil {
		return string(data), nil
	}
	if explicit {
		return "", cliError{Message: fmt.Sprintf("configuration file %s not found!", path), ShowHelp: true}
	}
	return "", cliError{Message: "Doxyfile not found and no input file specified!", ShowHelp: true}
}

func defaultPositional(values []string, fallback string) string {
	if len(values) == 0 {
		return fallback
	}
	return values[0]
}

func defaultConfigPath(values []string) (string, bool) {
	if len(values) == 0 {
		return "Doxyfile", false
	}
	return values[0], true
}

